import React, { useContext } from 'react';
import { useIntl } from 'react-intl';

import { TableIcon } from '@dynatrace/strato-icons';

import { Button } from '../../../buttons/button/Button.js';
import { Tooltip } from '../../../overlays/tooltip/Tooltip.js';
import { dataTableMessages } from '../../../tables/DataTable/messages.js';
import { DataTableContext } from '../../contexts/DataTableContext.js';
import { ColumnMinInstance } from '../../types/internal-table-types.js';
import { findColumnInstance } from '../../utils/column-utils.js';

/**
 * Button that triggers column settings modal.
 *
 * @returns minimal button with TableIcon
 */
export function ColumnSettingsButton(props: {
  onClick: () => void;
}): React.ReactElement {
  const intl = useIntl();
  const { columnVisibility, allColumns } = useContext(DataTableContext);
  let hiddenColumnCount = 0;

  const tooltipText = intl.formatMessage(dataTableMessages.columnSettingsLabel);

  for (const entry of Object.entries(columnVisibility)) {
    const state = entry[1];
    const identifier = entry[0];

    const findResult = findColumnInstance(
      (allColumns as ColumnMinInstance[]) ?? [],
      identifier,
    );

    if (!findResult?.columns && state === 'hidden') {
      hiddenColumnCount++;
    }
  }

  return (
    <Tooltip text={tooltipText}>
      <Button onClick={props.onClick} variant="default">
        <Button.Prefix>
          <TableIcon />
        </Button.Prefix>
        {hiddenColumnCount === 0
          ? intl.formatMessage({
              defaultMessage: 'Columns',
              id: 'F78crM1uQumIOJdh',
              description: 'Column settings button default text',
            })
          : intl.formatMessage(
              {
                defaultMessage:
                  '{hiddenColumnCount} {hiddenColumnCount, plural, one {column} other {columns}} hidden',
                id: 'aqGvcDl8n+XdhJiq',
                description: 'Column visibility button text',
              },
              { hiddenColumnCount },
            )}
      </Button>
    </Tooltip>
  );
}
